"use client";

import React, { useEffect, useState } from "react";
import { useTheme } from "next-themes";  // Importing the `useTheme` hook from next-themes
import Body from "./pages/Home/Body";
import Choose from "./pages/Home/Choose";
import Services from "./pages/Home/Services";


const Home: React.FC = () => {
  const { theme } = useTheme();  // Destructuring the theme and setTheme from useTheme
  const [mounted, setMounted] = useState<boolean>(false);  // useState with TypeScript type annotation

  // useEffect to ensure that the theme is applied only after the component has mounted
  useEffect(() => {
    setMounted(true);
  }, []);
  

  if (!mounted) return null;  // If the component hasn't mounted yet, render nothing

  return (
    <div className={`${theme === "dark" ? "bg-gray-800" : "bg-white"} px-10`}>
      <Body />
      <Services />
      <Choose />
    </div>
  );
};

export default Home;
